import {SEAM_PINS as P} from './pins.mjs';import {createSeamRepairLayer} from './layer.mjs';
const COMPILED=Object.freeze({file:'old-g1-seam-bounds-128x1320.png',bytes:410251,sha256:'f341594ca8e9540938254c195d49fddbf0d92024bc8f018355fba7f6dc4736cc',sourceSHA256:'ba5a9a1c08f0e7eb7e122324b76c04636edf57e73f750d837692af0196519497',sourceWidth:4812,sourceHeight:1719,cropX:3526,cropY:0,width:128,height:1320});
const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const oldRects=[[3526,0,3590,360],[3529,367,3654,451],[3526,460,3590,800],[3526,1130,3590,1320]],plateRect=[948,99,1065,679];
export async function loadSeamRepair({fetcher=fetch,decode=b=>createImageBitmap(new Blob([b])),crop=(im,x,y,w,h)=>createImageBitmap(im,x,y,w,h),signal}={}){const held=new Set(),cleanupErrors=[];let disposed=false,layer;const check=()=>{if(signal?.aborted)throw Error('SEAM_ABORTED')},release=im=>{if(!held.delete(im))return;try{im.close?.()}catch(e){cleanupErrors.push(e)}},cleanup=()=>{for(const im of [...held])release(im)};
 try{const groups=[];for(const [name,width,height,rects]of [[COMPILED.file,COMPILED.width,COMPILED.height,oldRects.map(([x,y,r,b])=>[x-COMPILED.cropX,y-COMPILED.cropY,r-COMPILED.cropX,b-COMPILED.cropY])],['new-seam-plate-original.png',1672,941,[plateRect]]]){check();const r=await fetcher(new URL('./assets/'+name,import.meta.url),{signal});if(!r.ok)throw Error('SEAM_INPUT_MISSING');const raw=await r.arrayBuffer(),b=new Uint8Array(raw instanceof ArrayBuffer?raw.slice(0):raw),pin=name===COMPILED.file?COMPILED:P[name];check();if(b.length!==pin.bytes||await hash(b)!==pin.sha256)throw Error('SEAM_INPUT_PIN');const full=await decode(b);held.add(full);check();if(full.width!==width||full.height!==height)throw Error('SEAM_IMAGE_DIMENSIONS');const pieces=[];for(const[x,y,right,bottom]of rects){check();const part=await crop(full,x,y,right-x,bottom-y);held.add(part);check();if(part===full||part.width!==right-x||part.height!==bottom-y)throw Error('SEAM_CROP_DIMENSIONS');pieces.push(part)}release(full);groups.push(pieces)}layer=createSeamRepairLayer({oldCrops:groups[0],plate:groups[1][0],plateSourceRect:plateRect});return Object.freeze({draw:layer.draw,cleanupErrors,dispose(){if(disposed)return;disposed=true;layer.dispose();cleanup()}})}catch(e){layer?.dispose();cleanup();throw e}}
